from __future__ import annotations

from hashlib import sha256

from django.core.cache import cache
from rest_framework.request import Request

from family_scheduler.client_app import ClientApp, canonicalize_client_app

DESKTOP_RESPONSE_CACHE_TTL_SECONDS = 30


def is_desktop_request(request: Request) -> bool:
    return (
        canonicalize_client_app(getattr(request, "client_app", None), default="")
        == ClientApp.DESKTOP
    )


def _version_key(namespace: str, scope_token: str) -> str:
    return f"desktop-response-cache:{namespace}:version:{scope_token}"


def _response_key(
    request: Request,
    *,
    namespace: str,
    scope_token: str,
    version: int,
) -> str:
    digest = sha256(request.get_full_path().encode("utf-8")).hexdigest()
    return (
        f"desktop-response-cache:{namespace}:{scope_token}:"
        f"user:{request.user.id}:v:{version}:{digest}"
    )


def _get_version(namespace: str, scope_token: str) -> int:
    version_key = _version_key(namespace, scope_token)
    version = cache.get(version_key)
    if version is None:
        cache.add(version_key, 1, timeout=None)
        version = cache.get(version_key) or 1
    return int(version)


def get_desktop_response_cache(
    request: Request,
    *,
    namespace: str,
    scope_token: str | int,
):
    if not request.user.is_authenticated or not is_desktop_request(request):
        return None

    version = _get_version(namespace, str(scope_token))
    return cache.get(
        _response_key(
            request,
            namespace=namespace,
            scope_token=str(scope_token),
            version=version,
        )
    )


def set_desktop_response_cache(
    request: Request,
    *,
    namespace: str,
    scope_token: str | int,
    payload,
    timeout: int = DESKTOP_RESPONSE_CACHE_TTL_SECONDS,
):
    if not request.user.is_authenticated or not is_desktop_request(request):
        return

    normalized_scope = str(scope_token)
    version = _get_version(namespace, normalized_scope)
    cache.set(
        _response_key(
            request,
            namespace=namespace,
            scope_token=normalized_scope,
            version=version,
        ),
        payload,
        timeout=timeout,
    )


def bump_desktop_response_cache_version(
    *,
    namespace: str,
    scope_token: str | int,
):
    version_key = _version_key(namespace, str(scope_token))
    try:
        cache.incr(version_key)
    except ValueError:
        current_version = cache.get(version_key) or 1
        cache.set(version_key, int(current_version) + 1, timeout=None)

def suggest_thread_title(message_text: str) -> str:
    normalized_text = " ".join(message_text.split())
    if not normalized_text:
        return DEFAULT_FAMILY_AGENT_THREAD_TITLE
    if len(normalized_text) <= 60:
        return normalized_text
    return f"{normalized_text[:57].rstrip()}..."


def _invalidate_family_agent_threads_cache(family: FamilyGroup) -> None:
    bump_desktop_response_cache_version(
        namespace=FAMILY_AGENT_THREADS_CACHE_NAMESPACE,
        scope_token=family.id,
    )


class FamilyAgentAccessMixin:
    def get_current_family(self, request: Request) -> FamilyGroup:
        user = cast(User, request.user)

        if not family_planner_feature_flags.is_enabled(user):
            raise NotFound("Family planner is not available.")

        family = get_user_immediate_family(user)
        if family is None:
            raise NotFound("Immediate family not found.")

        family = FamilyGroup.objects.select_related("feature_settings").get(
            id=family.id
        )
        if not family.feature_settings.agent_enabled:
            raise NotFound("Family planner is not enabled for this family.")

        has_permission, error_msg = validate_family_admin_permission(
            user,
            family,
            "access family planner",
        )
        if not has_permission and not user.is_staff:
            raise PermissionDenied(
                error_msg or "Only family admins can use the planner."
            )

        return family

    def get_active_threads_queryset(self, family: FamilyGroup):
        return FamilyAgentThread.objects.filter(
            family=family,
            is_archived=False,
        ).order_by("-updated_at", "-created_at")

    def get_default_thread(
        self, family: FamilyGroup, *, user: User
    ) -> FamilyAgentThread:
        thread = self.get_active_threads_queryset(family).first()
        if thread is not None:
            return thread
        return FamilyAgentThread.objects.create(
            family=family,
            created_by=user,
            title=DEFAULT_FAMILY_AGENT_THREAD_TITLE,
        )

    def get_thread_by_id(
        self, family: FamilyGroup, thread_id: str
    ) -> FamilyAgentThread:
        try:
            return FamilyAgentThread.objects.get(
                id=thread_id,
                family=family,
                is_archived=False,
            )
        except FamilyAgentThread.DoesNotExist as exc:
            raise Http404 from exc

    def resolve_thread(
        self,
        request: Request,
        family: FamilyGroup,
        *,
        user: User,
        thread_id: str | None = None,
    ) -> FamilyAgentThread:
        requested_thread_id = (
            thread_id
            or request.query_params.get("thread_id")
            or request.data.get("thread_id")
        )
        if requested_thread_id:
            return self.get_thread_by_id(family, requested_thread_id)
        return self.get_default_thread(family, user=user)


class FamilyAgentThreadView(FamilyAgentAccessMixin, APIView):
    def get(self, request: Request) -> Response:
        family = self.get_current_family(request)
        thread = self.resolve_thread(request, family, user=cast(User, request.user))
        serializer = FamilyAgentThreadSerializer(thread)
        return Response(serializer.data)


class FamilyAgentThreadListCreateView(FamilyAgentAccessMixin, APIView):
    def get(self, request: Request) -> Response:
        family = self.get_current_family(request)
        cached_payload = get_desktop_response_cache(
            request,
            namespace=FAMILY_AGENT_THREADS_CACHE_NAMESPACE,
            scope_token=family.id,
        )
        if cached_payload is not None:
            return Response(cached_payload)

        user = cast(User, request.user)
        self.get_default_thread(family, user=user)
        threads = self.get_active_threads_queryset(family)
        serializer = FamilyAgentThreadSerializer(threads, many=True)
        response = Response(serializer.data)
        set_desktop_response_cache(
            request,
            namespace=FAMILY_AGENT_THREADS_CACHE_NAMESPACE,
            scope_token=family.id,
            payload=response.data,
        )
        return response

    def post(self, request: Request) -> Response:
        family = self.get_current_family(request)
        user = cast(User, request.user)
        serializer = FamilyAgentThreadCreateSerializer(data=request.data)

